"""Sphinx hooks for docstrings and signatures generated by pybind11.

pybind11 puts each function's signature on the first line of its docstring; autodoc reads it from
there, and so does pybind11-stubgen for the ``.pyi`` stubs. For the HTML pages this module:

- shortens the precise stub-style types (``typing.SupportsInt | typing.SupportsIndex``,
  ``typing.Annotated[numpy.typing.NDArray[numpy.uint64], "[m, 1]"]``, ...) to readable ones
  (``int``, ``numpy.ndarray[numpy.uint64]``); the stubs keep the precise types;
- turns the "Overloaded function." block of an overloaded function into numbered overloads, each
  headed by its signature, and shows ``(...)`` instead of ``(*args, **kwargs)`` in the title;
- escapes ``*args``/``**kwargs`` in docstrings, which reStructuredText would read as emphasis.
"""
import re

RE_ARGS_KWARGS = re.compile(r'(?<![*\\])\*args|(?<!\\)\*\*kwargs')
RE_OVERLOAD = re.compile(r'^(\d+)\. (\w+)\((.*)\)( -> .+)?$')

# Stub-style type -> type shown in the docs. Applied in order.
_TYPE_REPLACEMENTS = [
    (re.compile(r'typing\.SupportsInt \| typing\.SupportsIndex'), 'int'),
    (re.compile(r'typing\.SupportsFloat \| typing\.SupportsIndex'), 'float'),
    (re.compile(r'typing\.Annotated\[numpy\.typing\.NDArray\[numpy\.(\w+)\], "[^"]*"\]'), r'numpy.ndarray[numpy.\1]'),
    (re.compile(r'typing\.Annotated\[(.+?), [^\]]*"\]'), r'\1'),
    (re.compile(r'numpy\.typing\.NDArray\[numpy\.(\w+)\]'), r'numpy.ndarray[numpy.\1]'),
    (re.compile(r'numpy\.typing\.ArrayLike'), 'array_like'),
    (re.compile(r'collections\.abc\.'), ''),
    (re.compile(r'typing\.'), ''),
    (re.compile(r'egttools\.numerical\.numerical_\.(?:\w+\.)*'), ''),
]


def simplify_types(text):
    """Shorten stub-style type annotations for display."""
    if not text:
        return text
    for pattern, replacement in _TYPE_REPLACEMENTS:
        text = pattern.sub(replacement, text)
    return text


def process_signature(app, what, name, obj, options, signature, return_annotation):
    doc = getattr(obj, '__doc__', None) or ''
    if signature and '(*args, **kwargs)' in signature and 'Overloaded function.' in doc:
        signature = '(...)'
    return simplify_types(signature), simplify_types(return_annotation)


def format_overloads(app, what, name, obj, options, lines):
    """Number the overloads of an overloaded function, each headed by its signature."""
    if not any(line.strip() == 'Overloaded function.' for line in lines):
        return
    out = []
    for line in lines:
        if line.strip() == 'Overloaded function.':
            out.append('This function has several overloads.')
            continue
        match = RE_OVERLOAD.match(line.strip())
        if match:
            number, function, arguments, returns = match.groups()
            out.append(f'.. rubric:: Overload {number}')
            out.append('')
            out.append(f'``{function}({simplify_types(arguments)}){simplify_types(returns or "")}``')
            out.append('')
            continue
        out.append(line)
    lines[:] = out


def fix_args_kwargs(app, what, name, obj, options, lines):
    for i, line in enumerate(lines):
        if line.startswith('``'):  # inside an overload signature literal
            continue
        lines[i] = RE_ARGS_KWARGS.sub(lambda m: m.group().replace('*', '\\*'), line)


def setup(app):
    # Run before napoleon (priority 500) so it parses each overload's sections normally.
    app.connect('autodoc-process-docstring', format_overloads, priority=400)
    app.connect('autodoc-process-docstring', fix_args_kwargs, priority=450)
    app.connect('autodoc-process-signature', process_signature)
    return {'parallel_read_safe': True}
